args <- commandArgs(trailingOnly=TRUE)
if(length(args)<3L)stop('Usage: Rscript regenerate_figures.R EXPERIMENT_ROOT OUTPUT_FOLDER NATIVE_CACHE')
p <- normalizePath(args[1],mustWork=TRUE)
cache <- normalizePath(args[3],mustWork=TRUE)
o <- args[2];dir.create(o,showWarnings=FALSE);dir.create(file.path(o,'figures'),showWarnings=FALSE);dir.create(file.path(o,'supplementary_tables'),showWarnings=FALSE)
cts<-c('Astro','Excit','Inhib','Oligo','OPC','Immune','Vascular');cols<-c(GAM6='#0072B2',contribution='#D55E00',expected_count='#009E73')
files<-c(S1_profile_predictions='gam6_no_composition_loo_r2/validation_GAM6_predictions.csv',S2_recovery_curves='gam6_no_composition_loo_r2/comparison_retention_curves.csv',S3_continuous_summary='continuous_associations_v1/association_summary.csv',S4_null_results='continuous_associations_v1/null_summary.csv',S5_eqtl_summary='eqtl_three_types_v1/detection_summary.csv',S7_eqtl_leakage='eqtl_three_types_v1/source_to_recipient_by_replicate.csv',S9_continuous_replicates='continuous_associations_v1/association_comparisons.csv',S10_eqtl_design='eqtl_three_types_v1/injected_gene_type_design.csv')
for(nm in names(files))file.copy(file.path(p,files[nm]),file.path(o,'supplementary_tables',paste0(nm,'.csv')),overwrite=TRUE)
write.csv(data.frame(table=names(files),source=unname(files),md5=unname(tools::md5sum(file.path(p,files)))),file.path(o,'supplementary_tables/source_manifest.csv'),row.names=FALSE)
read<-function(n)read.csv(file.path(p,files[n]));v<-read(1);cur<-read(2);a<-read(3);n<-read(4);eq<-read(5)
fig<-function(name,w,h,fun){for(ext in c('pdf','png')){f<-file.path(o,'figures',paste0(name,'.',ext));if(ext=='pdf')pdf(f,width=w,height=h,family='Helvetica',useDingbats=FALSE)else png(f,width=w,height=h,units='in',res=300,type='cairo');par(mar=c(4.4,4.5,2.8,1),mgp=c(2.7,.8,0),las=1,cex=.9);fun();dev.off()}}
legendm<-function(ms=names(cols))legend('bottomleft',legend=ms,col=cols[ms],lty=1,bty='n',cex=.75)
curve<-function(ct){plot(NA,xlim=c(0,100),ylim=c(0,1),xlab='Profiles retained (%)',ylab='Median recovery r',main=ct);for(m in names(cols)){d<-subset(cur,stage=='validation'&cell_type==ct&method==m&retention>0);d<-d[order(d$retention),];lines(d$retention*100,d$median_Pearson,col=cols[m],lwd=2)}}
fig('Figure_1_workflow',9,5,function(){par(mar=c(0,0,0,0));plot.new();plot.window(xlim=c(0,10),ylim=c(0,6));boxtext<-function(x,y,w,h,t){rect(x,y,x+w,y+h,col='#EEF4F7',border='#40627A');text(x+w/2,y+h/2,t,cex=.95)}
boxtext(.1,4.7,2.8,1,'Bulk RNA counts\nSingle-nucleus reference');boxtext(3.6,4.7,2.8,1,'CDSeq2 inference\nIndividual-level expression');boxtext(7.1,4.7,2.8,1,'Gene/type profiles\nUneven variation recovery');boxtext(.1,2.5,2.8,1.1,'20 reference donors\n40 training donors\n40 evaluation donors');boxtext(3.6,2.5,2.8,1.1,'Six observable features\nCell-type-specific GAMs\nNo phenotype or genotype input');boxtext(7.1,2.5,2.8,1.1,'Rank gene/type pairs\nSelect retention level\nKeep range diagnostics');boxtext(1,.3,3.5,1.1,'Continuous phenotypes\n189 signal and 200 null traits\nAssociation agreement');boxtext(5.5,.3,3.5,1.1,'Nominated eQTLs\n9 scenarios and BayesPrism\nSensitivity and attribution errors');arrows(c(2.9,6.4,5,2.9,6.4,8,7.2),c(5.2,5.2,4.6,3,3,2.4,2.4),c(3.5,7,5,3.5,7,7.2,2.8),c(5.2,5.2,3.7,3,3,1.5,1.5),length=.08,col='#40627A')})
med<-sapply(cts,function(ct)median(v$observed_r[v$cell_type==ct],na.rm=TRUE));sel<-sapply(cts,function(ct){d<-v[v$cell_type==ct,];d<-d[order(-d$variation_score,d$gene),];median(d$observed_r[1:400],na.rm=TRUE)})
write.csv(data.frame(cell_type=cts,all_median_r=med,GAM6_top20_median_r=sel),file.path(o,'supplementary_tables/S11_profile_medians.csv'),row.names=FALSE)
fig('Figure_2_expression_recovery',9,6.5,function(){par(mfrow=c(2,2));barplot(rbind(med,sel),beside=TRUE,col=c('#999999',cols[1]),names.arg=cts,las=2,ylim=c(0,1),ylab='Median recovery r',main='A  All versus selected profiles',cex.names=.8);legend('topright',c('All','GAM6 top 20%'),fill=c('#999999',cols[1]),bty='n',cex=.8);for(ct in c('Excit','Inhib','Oligo')){curve(ct);if(ct=='Oligo')legendm()}})
fig('Figure_3_continuous_associations',9,6.3,function(){par(mfrow=c(2,2));for(ct in c('Excit','Oligo'))for(metric in c('reference_agreement_among_calls','reference_recall_full_type')){plot(NA,xlim=c(10,100),ylim=c(0,100),xlab='Profiles retained (%)',ylab=if(metric=='reference_agreement_among_calls')'Agreement among calls (%)'else'Full-type reference recall (%)',main=paste(ct,'| signal fraction 0.50'));for(m in c('GAM6','contribution','expected_count')){d<-subset(a,source_type==ct&evaluated_type==ct&signal_fraction==.5&method==m);d<-d[order(d$retention),];lines(d$retention*100,d[[metric]]*100,col=cols[m],lwd=2)};if(ct=='Excit'&&metric=='reference_agreement_among_calls')legendm(c('GAM6','contribution','expected_count'))}})
fig('Figure_S11_eqtl',10,6,function(){par(mfrow=c(2,3));for(metric in c('detection_rate','pooled_FDP'))for(ct in c('Excit','Inhib','Oligo')){plot(NA,xlim=c(.45,.85),ylim=c(0,100),xaxt='n',xlab='Injected signal ratio',ylab=if(metric=='detection_rate')'Injected effects detected (%)'else'Pooled FDP (%)',main=ct);axis(1,c(.5,.8));for(m in c('GAM6','contribution','expected_count')){d<-subset(eq,engine=='CDSeq2'&cell_type==ct&score_scope=='scenario'&method==m&policy=='matched_tested_budget'&group=='top40'&pattern=='all'&signal_ratio>0);d<-d[order(d$signal_ratio),];stopifnot(nrow(d)==2);lines(d$signal_ratio,d[[metric]]*100,type='b',pch=16,col=cols[m],lwd=2)};d<-subset(eq,engine=='CDSeq2'&cell_type==ct&score_scope=='scenario'&method=='GAM6'&policy=='full_panel'&group=='all'&pattern=='all'&signal_ratio>0);lines(d$signal_ratio,d[[metric]]*100,type='b',pch=15,col='#555555',lty=2);if(ct=='Oligo'&&metric=='pooled_FDP')legend('topleft',c('GAM6','contribution','expected_count','Unfiltered'),col=c(cols[c('GAM6','contribution','expected_count')],'#555555'),lty=c(1,1,1,2),bty='n',cex=.7)}})
fig('Figure_S1_all_type_recovery',11,6,function(){par(mfrow=c(2,4));for(ct in cts)curve(ct);plot.new();legend('center',names(cols),col=cols,lty=1,bty='n')})
fig('Figure_S2_continuous_all_types',10,5,function(){par(mfrow=c(1,3),mar=c(5,5,3,1));for(metric in c('reference_agreement_among_calls','reference_recall_full_type')){mat<-sapply(c(.25,.5,.75),function(h)sapply(cts,function(ct){d<-subset(a,source_type==ct&evaluated_type==ct&method=='GAM6'&retention==.2&signal_fraction==h);d[[metric]]*100}));image(1:3,1:7,t(mat[7:1,]),zlim=c(0,100),col=hcl.colors(30,'Blues',rev=TRUE),axes=FALSE,xlab='Signal fraction',ylab='',main=if(metric=='reference_recall_full_type')'Full-type recall (%)'else'Agreement (%)');axis(1,1:3,c('.25','.50','.75'));axis(2,1:7,rev(cts),las=1);for(i in 1:7)for(j in 1:3)text(j,8-i,if(is.na(mat[i,j]))'NA'else sprintf('%.1f',mat[i,j]),cex=.75,col=if(is.finite(mat[i,j])&&mat[i,j]>60)'white'else'black')};d<-subset(n,cell_type=='ALL');barplot(d$probability_any_false_call*100,names.arg=c('CDSeq2','Observed'),col=c('#0072B2','#999999'),ylim=c(0,8),ylab='Null traits with any rejection (%)',main='200 global-null traits');abline(h=5,lty=2)})
print(data.frame(cts,med,sel));cat('Figures complete\n')

# Apply the revised presentation after rebuilding original source tables.
script_arg <- grep("^--file=", commandArgs(FALSE), value=TRUE)
script_dir <- dirname(normalizePath(sub("^--file=", "", script_arg[1])))
helper <- file.path(script_dir, 'cell_type_labels.R')
if(normalizePath(o) != normalizePath(script_dir)) {
  if(!file.copy(helper, file.path(o, 'cell_type_labels.R'), overwrite=TRUE)) stop('Cannot copy cell-type display helper')
}
status <- system2(file.path(R.home("bin"), "Rscript"),
                  c("--vanilla", shQuote(file.path(script_dir, "revised_figures.R")), shQuote(o)))
if(status != 0L) stop("Revised figure generation failed")
status <- system2(file.path(R.home('bin'), 'Rscript'), c('--vanilla', shQuote(file.path(script_dir,'prepare_standard_comparison.R')), shQuote(p), shQuote(cache), shQuote(o)))
if(status != 0L) stop('Standard BayesPrism comparison preparation failed')
status <- system2(file.path(R.home('bin'), 'Rscript'), c('--vanilla', shQuote(file.path(script_dir,'compute_ground_truth_benchmarks.R')), shQuote(p), shQuote(o), shQuote(cache)))
if(status != 0L) stop('Ground-truth benchmark calculation failed')
status <- system2(file.path(R.home('bin'), 'Rscript'), c('--vanilla', shQuote(file.path(script_dir,'prepare_expression_prioritization.R')), shQuote(p), shQuote(o)))
if(status != 0L) stop('Figure S4 selection preparation failed')
status <- system2(file.path(R.home('bin'), 'Rscript'), c('--vanilla', shQuote(file.path(script_dir,'exclude_continuous_donor.R')), shQuote(p), shQuote(o)))
if(status != 0L) stop('39-donor continuous reanalysis failed')
status <- system2(file.path(R.home('bin'), 'Rscript'), c('--vanilla', shQuote(file.path(script_dir,'additional_figures.R')), shQuote(o)))
if(status != 0L) stop('Supplementary figure generation failed')

status <- system2(file.path(R.home('bin'), 'Rscript'), c('--vanilla', shQuote(file.path(script_dir,'prepare_application_panels.R')), shQuote(p), shQuote(o)))
if(status != 0L) stop('Application-panel preparation failed')
status <- system2(file.path(R.home('bin'), 'Rscript'), c('--vanilla', shQuote(file.path(script_dir,'continuous_slope_sensitivity.R')), shQuote(p), shQuote(o)))
if(status != 0L) stop('Continuous donor-sensitivity diagnostic failed')
status <- system2(file.path(R.home('bin'), 'Rscript'), c('--vanilla', shQuote(file.path(script_dir,'application_figures.R')), shQuote(o)))
if(status != 0L) stop('Application figures failed')
# additional_figures.R writes the final S7 directly from the 39-donor tables.
for(ext in c('pdf','png'))unlink(file.path(o,'figures',paste0('Figure_3_continuous_associations.',ext)))
python <- Sys.getenv('CDSEQ2_FIGURE_PYTHON', 'python3')
status <- system2(python,c(shQuote(file.path(script_dir,'draw_workflow.py')),shQuote(o)))
if(status != 0L) stop('Workflow illustration failed; Python with reportlab is required')
status <- system2(file.path(R.home('bin'), 'Rscript'), c('--vanilla', shQuote(file.path(script_dir,'eqtl_accuracy_metrics.R')), shQuote(o)))
if(status != 0L) stop('Precision-recall, F1 and matched-FDP calculation failed')
status <- system2(file.path(R.home('bin'), 'Rscript'), c('--vanilla', shQuote(file.path(script_dir,'eqtl_accuracy_figures.R')), shQuote(o)))
if(status != 0L) stop('Accuracy-coverage figures failed')
status <- system2(file.path(R.home('bin'), 'Rscript'), c('--vanilla', shQuote(file.path(script_dir,'figure_eqtl_rankings.R')), shQuote(o)))
if(status != 0L) stop('Nominated eQTL ranking figures failed')
table_files <- list.files(file.path(o,'supplementary_tables'),pattern='^S[0-9]+_.*\\.csv$',full.names=TRUE)
write.csv(data.frame(file=basename(table_files),md5=unname(tools::md5sum(table_files))),file.path(o,'supplementary_tables/deliverable_checksums.csv'),row.names=FALSE)
